// Native-only touches for the Android app (AR-3..AR-5). main.ts imports this module dynamically and
// only when Capacitor.isNativePlatform(), so the web build never loads it or the plugins it uses.
// The splash screen and launcher icon are native resources, generated by @capacitor/assets (AR-5).
import { listenToBackButton } from './back-button'
import { followThemeInStatusBar } from './status-bar'

export async function startNative() {
  followThemeInStatusBar()
  await listenToBackButton()
}
